19	// seedPromotableMember builds a member corpus whose (intentSig, heads) task is
20	// promotable (12 corroborated successes + noise), so it surfaces as a member
21	// task candidate for the workspace judgment layer.
22	func seedPromotableMember(t *testing.T, brainDir, repoKey, intentSig string, heads ...string) {
23		t.Helper()
24		path, err := base.PrepareBrainRelativeSQLiteFile(brainDir, patterncore.CorpusPath)
25		if err != nil {
26			t.Fatal(err)
27		}
28		db, err := sql.Open(sqlitedriver.Name, path)
29		if err != nil {
30			t.Fatal(err)
31		}
32		defer db.Close()
33		for _, s := range patterncore.CorpusSchema {
34			if _, err := db.Exec(s); err != nil {
35				t.Fatalf("schema: %v", err)
36			}
37		}
38		now := time.Now()
39		for i := 0; i < 12; i++ {
40			id := fmt.Sprintf("%s:ok%d", intentSig, i)
41			patterntest.InsertCorpusEpisode(t, db, id, intentSig, "success", len(heads), now)
42			patterntest.InsertCorpusShape(t, db, id, heads...)
43			db.Exec(`INSERT INTO episode_facts (episode_id, fact_id, kind, paths, weight) VALUES (?,?,?,?,2)`,
44				id, "fact:"+intentSig, "architecture", "ops/x.go")
45		}
46		for i := 0; i < 120; i++ {
47			id := fmt.Sprintf("%s:noise%d", intentSig, i)
48			patterntest.InsertCorpusEpisode(t, db, id, "other:thing", "neutral", 2, now)
49			patterntest.InsertCorpusShape(t, db, id, "ls", "cat")
50		}
51		if err := patterncore.BuildCandidates(db, repoKey, now); err != nil {
52			t.Fatal(err)
53		}
54	}
55	
56	// releaseGroupingAgent groups repos whose task intent mentions "release" into one
57	// cross-repo family (with each repo's actual commands); it rejects generic git.
58	func releaseGroupingAgent(t *testing.T) base.DistillAgentRunner {
59		return func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
60			var payload struct {
61				Repos map[string][]map[string]any `json:"repos"`
62			}
63			if err := json.Unmarshal(input, &payload); err != nil {
64				t.Fatalf("family proposal input not JSON: %v\n%s", err, input)
65			}
66			var perRepo []map[string]any
67			generic := true
68			for repo, tasks := range payload.Repos {
69				for _, tk := range tasks {
70					intent := fmt.Sprint(tk["intent"])
71					if strings.Contains(intent, "release") {
72						perRepo = append(perRepo, map[string]any{"repo_key": repo, "commands": tk["commands"]})
73						generic = false
74					}
75				}
76			}
77			verdict := "accepted"
78			if generic { // only generic git tasks present
79				verdict = "rejected"
80			}
81			resp := map[string]any{"families": []map[string]any{{
82				"title":           "release the build",
83				"trigger":         "shipping a release",
84				"purpose":         "build then publish a release",
85				"common_workflow": []string{"build", "publish release"},
86				"per_repo":        perRepo,
87				"verdict":         verdict,
88			}}}
89			b, _ := json.Marshal(resp)
90			return string(b), nil
91		}
92	}
