111	// SR5(1): equivalent release workflows with DIFFERENT command names produce ONE
112	// cross-repo family after agent judgment (exact aggregation never would).
113	func TestWorkspaceFamilyMergesEquivalentWorkflows(t *testing.T) {
114		t.Parallel()
115		env, manifest := twoRepoWorkspace(t,
116			"gh/acme/a", "release:build", []string{"mise build", "mise deploy"},
117			"gh/acme/b", "release:ship", []string{"make build", "make release"})
118	
119		stats, err := proposeWorkspaceFamilies(context.Background(), env, manifest, t.TempDir(), "codex", "", "", releaseGroupingAgent(t), time.Now())
120		if err != nil {
121			t.Fatal(err)
122		}
123		if stats.Verified != 1 {
124			t.Fatalf("expected 1 accepted family, got %+v", stats)
125		}
126		wsDir, _ := workspaceStore(env).Dir("plat")
127		fams := loadAcceptedWorkspaceFamilies(wsDir)
128		if len(fams) != 1 {
129			t.Fatalf("expected 1 family, got %d", len(fams))
130		}
131		if fams[0].RepoCount() != 2 {
132			t.Errorf("family must span 2 repos, got %d: %+v", fams[0].RepoCount(), fams[0].PerRepo)
133		}
134		// SR5(3): the family records the per-repo variation (different command names).
135		cmds := map[string]string{}
136		for _, v := range fams[0].PerRepo {
137			cmds[v.RepoKey] = strings.Join(v.Commands, ",")
138		}
139		if !strings.Contains(cmds["gh/acme/a"], "mise deploy") || !strings.Contains(cmds["gh/acme/b"], "make release") {
140			t.Errorf("family must keep each repo's actual commands, got %v", cmds)
141		}
142		// And the synthesis evidence surfaces the per-repo variations.
143		ev := buildWorkspaceFamilyEvidence(fams[0])
144		if !strings.Contains(ev, "Per-repo variations") || !strings.Contains(ev, "mise deploy") || !strings.Contains(ev, "make release") {
145			t.Errorf("workspace family evidence missing per-repo variations:\n%s", ev)
146		}
147	}
