149	// SR5(2): two repos that only share generic git commit/push produce NO accepted
150	// family (so no workspace skill).
151	func TestWorkspaceFamilyRejectsGeneric(t *testing.T) {
152		t.Parallel()
153		env, manifest := twoRepoWorkspace(t,
154			"gh/acme/a", "commit:push", []string{"git add", "git push"},
155			"gh/acme/b", "commit:push", []string{"git add", "git push"})
156	
157		if _, err := proposeWorkspaceFamilies(context.Background(), env, manifest, t.TempDir(), "codex", "", "", releaseGroupingAgent(t), time.Now()); err != nil {
158			t.Fatal(err)
159		}
160		wsDir, _ := workspaceStore(env).Dir("plat")
161		if fams := loadAcceptedWorkspaceFamilies(wsDir); len(fams) != 0 {
162			t.Errorf("generic git workflows must not produce an accepted workspace family, got %d", len(fams))
163		}
