72	// openMemoryStateFileExpected shares the identity and alias protections with
73	// readers that decode directly from the descriptor. The caller closes the file.
74	func openMemoryStateFileExpected(brainDir, rel, label string, expected os.FileInfo) (*os.File, bool, error) {
75		clean, err := base.CleanBrainRelativePath(filepath.ToSlash(strings.TrimSpace(rel)))
76		if err != nil {
77			return nil, false, fmt.Errorf("%s: %s has an unsafe path %q: %w", brainstore.StateUnsafeCode, label, rel, err)
78		}
79		if err := base.RejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
80			return nil, false, fmt.Errorf("%s: inspect %s %s: %w", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean), err)
81		}
82		path := filepath.Join(brainDir, clean)
83		before, err := memoryStateLstat(path)
84		if err != nil {
85			if os.IsNotExist(err) {
86				return nil, false, nil
87			}
88			return nil, false, fmt.Errorf("%s: inspect %s %s: %w", brainstore.StateCorruptCode, label, filepath.ToSlash(clean), err)
89		}
90		if before.Mode()&os.ModeSymlink != 0 || !before.Mode().IsRegular() {
91			return nil, true, fmt.Errorf("%s: %s is not a regular file: %s", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean))
92		}
93		if expected != nil && !os.SameFile(expected, before) {
94			return nil, true, fmt.Errorf("%s: %s changed after directory enumeration: %s: %w", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean), errMemoryStateEnumerationStale)
95		}
96		f, err := memoryStateOpenFile(path, os.O_RDONLY|base.FileLockOpenFlags()|base.MemoryStateReadOpenFlags(), 0)
97		if err != nil {
98			return nil, true, fmt.Errorf("%s: open %s %s: %w", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean), err)
99		}
100		success := false
101		defer func() {
102			if !success {
103				_ = f.Close()
104			}
105		}()
106		opened, err := f.Stat()
107		if err != nil || !opened.Mode().IsRegular() || !os.SameFile(before, opened) {
108			return nil, true, fmt.Errorf("%s: %s changed or became unsafe while opening: %s", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean))
109		}
110		after, err := memoryStateLstat(path)
111		if err != nil || after.Mode()&os.ModeSymlink != 0 || !os.SameFile(opened, after) {
112			return nil, true, fmt.Errorf("%s: %s changed or became unsafe while opening: %s", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean))
113		}
114		if err := base.RejectOpenFileAlias(path, f, label); err != nil {
115			return nil, true, fmt.Errorf("%s: validate opened %s %s: %w", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean), err)
116		}
117		success = true
118		return f, true, nil
119	}
