129	// readMemoryStateDirectory uses the directory descriptor for enumeration and
130	// reads ceiling+1 entries so callers know when completeness was lost. It never
131	// silently treats a truncated inventory as complete.
132	func readMemoryStateDirectory(brainDir, rel, label string, ceiling int) (memoryStateDirectory, error) {
133		if ceiling < 1 {
134			ceiling = memoryStateInventoryMaxEntries
135		}
136		clean, err := base.CleanBrainRelativePath(filepath.ToSlash(strings.TrimSpace(rel)))
137		if err != nil {
138			return memoryStateDirectory{Degraded: true}, fmt.Errorf("%s: %s has an unsafe path %q: %w", brainstore.StateUnsafeCode, label, rel, err)
139		}
140		if err := base.RejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
141			return memoryStateDirectory{Degraded: true}, fmt.Errorf("%s: inspect %s %s: %w", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean), err)
142		}
143		path := filepath.Join(brainDir, clean)
144		before, err := memoryStateLstat(path)
145		if err != nil {
146			if os.IsNotExist(err) {
147				return memoryStateDirectory{}, nil
148			}
149			return memoryStateDirectory{Degraded: true}, fmt.Errorf("%s: inspect %s %s: %w", brainstore.StateCorruptCode, label, filepath.ToSlash(clean), err)
150		}
151		if before.Mode()&os.ModeSymlink != 0 || !before.IsDir() {
152			return memoryStateDirectory{Present: true, Degraded: true}, fmt.Errorf("%s: %s is not a directory: %s", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean))
153		}
154		dir, err := memoryStateOpenFile(path, os.O_RDONLY|base.FileLockOpenFlags()|base.MemoryStateReadOpenFlags(), 0)
155		if err != nil {
156			return memoryStateDirectory{Present: true, Degraded: true}, fmt.Errorf("%s: open %s %s: %w", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean), err)
157		}
158		defer dir.Close()
159		opened, err := dir.Stat()
160		if err != nil || !opened.IsDir() || !os.SameFile(before, opened) {
161			return memoryStateDirectory{Present: true, Degraded: true}, fmt.Errorf("%s: %s changed or became unsafe while opening: %s", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean))
162		}
163		after, err := memoryStateLstat(path)
164		if err != nil || after.Mode()&os.ModeSymlink != 0 || !os.SameFile(opened, after) {
165			return memoryStateDirectory{Present: true, Degraded: true}, fmt.Errorf("%s: %s changed or became unsafe while opening: %s", brainstore.StateUnsafeCode, label, filepath.ToSlash(clean))
166		}
167		entries, err := dir.ReadDir(ceiling + 1)
168		if err != nil && !errors.Is(err, io.EOF) {
169			return memoryStateDirectory{Present: true, Degraded: true}, fmt.Errorf("%s: read %s %s: %w", brainstore.StateCorruptCode, label, filepath.ToSlash(clean), err)
170		}
171		result := memoryStateDirectory{Entries: entries, Present: true, Total: len(entries)}
172		if len(entries) > ceiling {
173			result.Entries = entries[:ceiling]
174			result.Truncated = true
175			result.Degraded = true
176		}
