package cli

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
)

type versionedTestDoc struct {
	SchemaVersion int    `json:"schema_version"`
	Known         string `json:"known"`
}

// A document written by a different build of our own writer at a supported
// schema version carries fields this build does not declare. For a reader that
// is routine skew, not corruption.
func TestDecodeVersionedJSONBody_TolerantModeAcceptsUnknownFields(t *testing.T) {
	t.Parallel()

	var got versionedTestDoc
	if _, err := decodeVersionedJSONBody([]byte(`{"schema_version":3,"known":"kept","retired_field":0}`), &got, true); err != nil {
		t.Fatalf("unknown field must not fail a reader: %v", err)
	}
	if got.Known != "kept" {
		t.Fatalf("known field lost during tolerant decode: %+v", got)
	}
}

// Writers keep the opposite answer: re-encoding from a struct that never saw a
// field erases it, so an unrecognised field must stop the write.
func TestDecodeVersionedJSONBody_StrictModeStillGuardsWriters(t *testing.T) {
	t.Parallel()

	var got versionedTestDoc
	_, err := decodeVersionedJSONBody([]byte(`{"schema_version":3,"known":"kept","retired_field":0}`), &got, false)
	if !isUnknownFieldError(err) {
		t.Fatalf("a writer must refuse a field it cannot round-trip, got: %v", err)
	}
}

// Tolerating unknown fields may not widen into tolerating malformed bytes or a
// second document, in either mode.
func TestDecodeStrictVersionedJSON_RejectsRealCorruption(t *testing.T) {
	t.Parallel()

	for name, data := range map[string]string{
		"malformed":     `{"schema_version":3,`,
		"trailing":      `{"schema_version":3}{"schema_version":3}`,
		"wrong type":    `{"schema_version":3,"known":123}`,
		"not an object": `["schema_version"]`,
	} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			var got versionedTestDoc
			if _, err := decodeStrictVersionedJSON([]byte(data), &got, 3, "test document"); err == nil {
				t.Fatalf("%s must be rejected", name)
			} else if !strings.Contains(err.Error(), brainstore.StateCorruptCode) {
				t.Fatalf("%s must classify as %s, got: %v", name, brainstore.StateCorruptCode, err)
			}

			var tolerant versionedTestDoc
			if _, err := decodeVersionedJSONBody([]byte(data), &tolerant, true); err == nil {
				t.Fatalf("%s must be rejected by the tolerant reader too", name)
			}
		})
	}
}

// A newer schema version keeps its own distinct, non-corrupt classification.
func TestDecodeStrictVersionedJSON_NewerVersionStillUnsupported(t *testing.T) {
	t.Parallel()

	var got versionedTestDoc
	_, err := decodeStrictVersionedJSON([]byte(`{"schema_version":9}`), &got, 3, "test document")
	if err == nil || !strings.Contains(err.Error(), memoryErrUnsupportedVersion) {
		t.Fatalf("newer schema must stay %s, got: %v", memoryErrUnsupportedVersion, err)
	}
}

// The tolerant retry re-decodes into a target the aborted strict pass already
// touched. Composite fields must come back exactly as a single clean decode
// would leave them, with nothing merged in from the first attempt.
func TestDecodeVersionedJSONBody_RetryDoesNotMergeIntoPartialTarget(t *testing.T) {
	t.Parallel()

	type doc struct {
		SchemaVersion int               `json:"schema_version"`
		Items         []string          `json:"items"`
		Labels        map[string]string `json:"labels"`
	}

	var got, want doc
	if _, err := decodeVersionedJSONBody([]byte(`{"schema_version":3,"items":["a","b"],"labels":{"k":"v"},"retired_field":1}`), &got, true); err != nil {
		t.Fatalf("unknown field must not fail: %v", err)
	}
	if _, err := decodeVersionedJSONBody([]byte(`{"schema_version":3,"items":["a","b"],"labels":{"k":"v"}}`), &want, true); err != nil {
		t.Fatalf("clean document must not fail: %v", err)
	}
	if len(got.Items) != len(want.Items) || len(got.Labels) != len(want.Labels) {
		t.Fatalf("retry merged into a partial target: got %+v, want %+v", got, want)
	}
	for i := range want.Items {
		if got.Items[i] != want.Items[i] {
			t.Fatalf("retry merged into a partial target: got %+v, want %+v", got, want)
		}
	}
}

// Trailing data keeps its own classification rather than being folded into the
// generic parse failure, because callers report it differently.
func TestDecodeVersionedJSONBody_TrailingDataIsDistinct(t *testing.T) {
	t.Parallel()

	var got versionedTestDoc
	if _, err := decodeVersionedJSONBody([]byte(`{"schema_version":3} {"schema_version":3}`), &got, true); !errors.Is(err, errTrailingJSONData) {
		t.Fatalf("want errTrailingJSONData, got: %v", err)
	}
}

func writeTestManifest(t *testing.T, body string) string {
	t.Helper()
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, exportManifestFileName), []byte(body), 0o600); err != nil {
		t.Fatal(err)
	}
	return dir
}

// The real-world regression: manifests written before commit cc5c5798 carry
// sources.seed.history_coverage.checkpointed_unexported_commits, a field since
// retired at the same schema version 3. Every such brain read as corrupt, which
// turned off all sources and left the memory worker retrying forever.
func TestLoadBrainManifest_RetiredFieldFromOlderBuildStillReads(t *testing.T) {
	t.Parallel()

package cli

import (
	"path"
	"strings"
	"testing"
	"time"

	"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
)

// privacyPathHostileIDs are the session ids that turn a filename-construction
// bug into an outage. The colon cases are the ones that mattered: this tool's
// own id vocabulary prints them, so an operator pasting an id it emitted was
// enough to make `privacy exclude` and `privacy purge` fail outright on
// Windows.
var privacyPathHostileIDs = []string{
	"session:totally-made-up-12345",
	"conversation-session:8b1c0027",
	"fact:8932cffc31492ddfd72dae32",
	"history:abc/def",
	`back\slash`,
	`star*and?question`,
	`quote"lt<gt>pipe|`,
	"trailing ",
	"trailing.",
	"with%percent",
	"CON", "con", "NUL", "Com1", "LPT9",
	"73b0b938-93e4-4771-901e-43227e8b904b",
}

// TestPrivacyTransactionPathIsAFilenameOnEveryPlatform pins the invariant the
// escaping exists to provide.
//
// It is written as a property of the path rather than as a Windows test on
// purpose: the bug only *fired* on Windows (ERROR_INVALID_PARAMETER, "The
// parameter is incorrect"), but the defect is that a filename was built with
// url.PathEscape, which is specified against URL path segments and therefore
// leaves a colon alone. Asserting the property makes the check run on every
// platform in CI instead of only on the two shards that caught it.
func TestPrivacyTransactionPathIsAFilenameOnEveryPlatform(t *testing.T) {
	for _, id := range privacyPathHostileIDs {
		rel := privacyTransactionRel(id)
		if !strings.HasPrefix(rel, historyDirName+"/privacy/") {
			t.Fatalf("privacyTransactionRel(%q) = %q, want it under %s/privacy/", id, rel, historyDirName)
		}
		name := path.Base(rel)
		// The characters no Windows filesystem accepts in a name. The colon is
		// the one url.PathEscape let through, because `a:b` is a legal URL path
		// segment and an NTFS alternate data stream.
		if idx := strings.IndexAny(name, `<>:"/\|?*`); idx >= 0 {
			t.Fatalf("privacyTransactionRel(%q) produced filename %q containing the illegal character %q", id, name, name[idx])
		}
		for _, r := range name {
			if r < 0x20 || r == 0x7f {
				t.Fatalf("privacyTransactionRel(%q) produced filename %q containing a control byte %q", id, name, r)
			}
		}
		// Windows silently strips a trailing dot or space, so a name that ends
		// in one does not round-trip to the file that was written.
		if strings.HasSuffix(name, ".") || strings.HasSuffix(name, " ") {
			t.Fatalf("privacyTransactionRel(%q) produced filename %q ending in a dot or space", id, name)
		}
		stem := strings.TrimSuffix(name, ".json")
		if stem == name {
			t.Fatalf("privacyTransactionRel(%q) produced filename %q without the .json suffix", id, name)
		}
		// A reserved device name is reserved WITH an extension too: CON.json is
		// the console, not a file.
		if windowsReservedDeviceNames[strings.ToUpper(stem)] {
			t.Fatalf("privacyTransactionRel(%q) produced reserved device name %q", id, name)
		}
	}
}

// TestPrivacyTransactionPathIsInjective is the property that makes the escaping
// safe to change: two different sessions must never share a transaction record,
// or excluding one would overwrite the durable receipt of the other.
func TestPrivacyTransactionPathIsInjective(t *testing.T) {
	seen := map[string]string{}
	for _, id := range append(append([]string(nil), privacyPathHostileIDs...),
		"a:b", "a%3Ab", "a/b", "a%2Fb", "CON", "%43ON", "secret-sess", "clean-sess") {
		rel := privacyTransactionRel(id)
		if other, ok := seen[rel]; ok && other != id {
			t.Fatalf("session ids %q and %q both map to %q", other, id, rel)
		}
		seen[rel] = id
	}
}

// TestPrivacyTransactionPathIsUnchangedForCapturedSessionIDs pins the migration
// claim in escapePrivacyTransactionID: captured session ids are UUIDs, none of
// their characters were ever escaped, and the fix must not rename a single
// record that exists on a real brain.
